$labels=['name'=>'Nama','title'=>'Judul','user_id'=>'ID Warga','resident_id'=>'ID Warga','house_id'=>'ID Rumah','invoice_id'=>'ID Tagihan','payment_batch_id'=>'ID Pembayaran Gabungan','invoice_template_id'=>'ID Template','invoice_template_run_id'=>'ID Penerbitan','billing_period'=>'Periode Tagihan','due_date'=>'Jatuh Tempo','components'=>'Komponen','recipient_mode'=>'Penerima','resident_ids'=>'ID Warga Terpilih','due_day'=>'Tanggal Jatuh Tempo','due_month_offset'=>'Selisih Bulan Jatuh Tempo','apply_house_tariff'=>'Aturan Rumah Kosong','is_active'=>'Aktif','type'=>'Jenis','source'=>'Sumber','category'=>'Kategori','total_cashflow'=>'Nominal Kas','total_amount'=>'Nominal Tagihan','transaction_date'=>'Tanggal Transaksi','status'=>'Status','paid_at'=>'Waktu Pembayaran','verified_at'=>'Waktu Verifikasi','verified_by'=>'ID Verifikator','payment_method'=>'Metode','method'=>'Metode','number'=>'Nomor Kuitansi','next_action_date'=>'Jadwal Tindak Lanjut','assigned_to'=>'ID Penanggung Jawab','rejection_reason'=>'Alasan Penolakan','payment_note'=>'Catatan Pembayaran','note'=>'Catatan','period'=>'Bulan Kas','closed_at'=>'Waktu Penutupan','closed_by'=>'ID Pengurus Penutupan','reopen_reason'=>'Alasan Buka Kembali','issued_count'=>'Tagihan Terbit','skipped_count'=>'Penerima Dilewati','has_attachment'=>'Ada Lampiran'];
$display=function($key,$value){
 if($value===null || $value==='') return '—';
 if(in_array($key,['apply_house_tariff','is_active','has_attachment'])) return $value?'Ya':'Tidak';
 if($key==='category') return \App\Enums\CashflowCategory::tryFrom($value)?->label() ?? $value;
 if(in_array($key,['total_cashflow','total_amount'])) return 'Rp '.number_format($value,2,',','.');
 if($key==='components') { $items=is_array($value)?$value:json_decode($value,true); return collect($items ?? [])->map(fn($item)=>($item['name'] ?? '').': Rp '.number_format($item['amount'] ?? 0,0,',','.'))->implode('; '); }
 if(is_array($value)) return implode(', ',$value);
 return ['unpaid'=>'Belum Dibayar','pending'=>'Menunggu Verifikasi','verified'=>'Terverifikasi','rejected'=>'Ditolak','open'=>'Terbuka','closed'=>'Ditutup / Selesai','cash'=>'Tunai','transfer'=>'Transfer','income'=>'Pemasukan','expense'=>'Pengeluaran','manual'=>'Manual','invoice'=>'Tagihan','all'=>'Semua Warga Aktif','selected'=>'Warga Terpilih','contacted'=>'Sudah Dihubungi','promised'=>'Janji Bayar','scheduled'=>'Hubungi Kembali'][$value] ?? $value;
};
