<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Waktu</th><th>Pelaku</th><th>Aktivitas</th><th>Perubahan</th></tr></thead><tbody>@forelse($logs as $log)<tr><td class="text-nowrap">{{ $log->created_at->format('d/m/Y H:i:s') }} WIB</td><td>{{ $log->actor_name }}</td><td>{{ \App\Http\Controllers\Pengurus\ActivityLogController::ENTITIES[$log->entity_type] ?? $log->entity_type }} #{{ $log->entity_id }}<small class="d-block">{{ ['created'=>'Ditambahkan','updated'=>'Diubah','deleted'=>'Dihapus'][$log->event] }}</small></td><td><details><summary>Lihat nilai sebelum / sesudah</summary><div class="table-responsive mt-2"><table class="table table-sm"><thead><tr><th>Data</th><th>Sebelum</th><th>Sesudah</th></tr></thead><tbody>@foreach(array_unique([...array_keys($log->before ?? []),...array_keys($log->after ?? [])]) as $key)@if(($log->before[$key] ?? null)!==($log->after[$key] ?? null))<tr><td>{{ $labels[$key] ?? $key }}</td><td class="text-break">{{ $display($key,$log->before[$key] ?? null) }}</td><td class="text-break">{{ $display($key,$log->after[$key] ?? null) }}</td></tr>@endif @endforeach</tbody></table></div></details></td></tr>@empty<tr><td colspan="4">Belum ada aktivitas yang sesuai filter.</td></tr>@endforelse</tbody></table></div><div class="card-footer bg-white">{{ $logs->links() }}</div></div>
